"use strict";{let o=`
<form id="confirmemail">
<webui-input-text theme="primary" name="displayName" label="Display Name" autofocus></webui-input-text>
<webui-input-text theme="primary" name="password" type="password" label="Password"></webui-input-text>
<webui-input-text theme="primary" name="confirmPassword" type="password" label="Confirm Password"></webui-input-text>
<webui-flex justify="end" align="center" class="pa-3">
    <webui-button type="submit" theme="primary" start-icon="confirm">Confirm Email</webui-button>
</webui-flex>
<webui-alert severity="danger"></webui-alert>
</form>
`;webui.define("app-confirmemail",{content:!0,watchVisibility:!1,isInput:!1,preload:"",flags:[],attr:["height","max-height"],attrChanged(i,s){const e=this;switch(i){case"height":e.style.height=webui.pxIfNumber(s);break;case"maxHeight":e.style.maxHeight=webui.pxIfNumber(s);break}},connected(){this.setupComponent()},setupComponent(){const i=this;i.innerHTML=o;let s=i.querySelector("#confirmemail"),e=i.querySelector("webui-alert");s.addEventListener("submit",n=>{n.stopPropagation(),n.preventDefault(),e.setValue();const u=new FormData(s),t=Object.fromEntries(u);t.token=location.pathname.split("/").pop();try{webui.fromBase64(t.token)}catch{e.setValue("Invalid token");return}if(!t.token){e.setValue("Missing expected token");return}if(!t.displayName){e.setValue("Please enter a display name");return}if(!t.password){e.setValue("Password is required");return}if(!t.confirmPassword){e.setValue("Please confirm your password");return}if(t.password!==t.confirmPassword){e.setValue("Password and Confirm Password do not match");return}let r;return webui.fetchApi("user/confirm",t).then(a=>(r=a,r.text())).then(a=>{r.status===200?(webui.alert(a||"Email confirmed and account successfully setup. You may now sign-in with your email and password.","success"),webui.navigateTo("/signin")):e.setValue(a||"Failed to finish setting up account.")}).catch(a=>{e.setValue(`Error: ${a}`)}),!1})}})}
